          "The same handle can appear on multiple platforms, and a rename can leave the same account under different labels. Record the actual platform and verifiable profile URL, plus a stable identifier if available through authorized access. Keep the capture time separate from the period covered. Current followers, ending followers, net growth and newly gained followers describe different quantities. Use an Instagram follower change log to keep event dates distinct from capture dates. Preserve the original displayed string and surface when a value is abbreviated. Compare records only after aligning what they count and when. If one comes from a profile header and one from an owner’s monthly report, name both surfaces and identify the question they can support. A monthly reporting row may still have an extraction timestamp on the next day. Record the reporting time zone so the overnight difference can be explained. A missing account identifier is material when the report refers to two similarly named profiles. Ask for the link before spending time reconciling the numbers."
