          "发布前定义每条片第几天核对、用哪个账号数据、哪些内容保留自然观察。每条记录主题、发布时间、分发来源、播放或触达、主页访问、可归因关注及是否有付费。分清按帖关注和账号日净增。用创作者活动衡量指南标注每项数字的分母和出处。不要把不同周的整个账号增长直接归给某一条视频。假设短片 A 和 B 分别在周一和周五发布，先比较发布后相同天数，再保留工作日与周末是可能差异这一事实。把没有提供的字段留空并解释。",
          "Decide the check-in age, source account and organic scope before the first post. Record the topic, release date, distribution source, views or reach, profile visits, attributable follows where available and any promotion. A post-level follows field and daily net growth for an account measure different things. Use the creator campaign measurement guide to note the source and denominator for each row. Keep the full-account change separate from any result attributed to a video. If videos A and B were published on Monday and Friday, compare them at the same age while retaining day of week as a possible difference. Leave unavailable fields open with a clear note about why. If a teammate captures the account total three days later than planned, log the actual date rather than entering the number into the planned window. A useful first report can show the main comparable rows and a second group for exploratory observations. Review whether the account and topic stayed similar enough for the comparison, and mark any major change that would matter to the next test."
