          "先问承诺是帮助策划自然内容，还是以不明方式新增关注者。若要求账号密码、登录验证码或不透明授权，通过官方 App 处理账号，不向服务交出凭证。TikTok反欺骗行为说明介绍平台对虚假互动的治理。平台政策可帮助识别不合规承诺，但不能证明某一账号或某条增长曲线造假。对合作报告只写已观察事实，例如没有提供分发来源、同一时期还开展付费活动。把无法确认的说法留作开放问题。教育团队识别证据缺口比发一张单指标排名更能帮助下一次决策。",
          "Ask whether the offer is for content planning and editing or claims to add followers through an undisclosed source. If it requests a password, sign-in code or unclear app permission, use the official account surface to review access. The TikTok deceptive behavior overview describes how the platform approaches fake engagement. A platform rule is useful context for assessing an offer. It cannot prove that an individual account or growth curve was manipulated. Use factual reporting language such as missing distribution data or paid promotion running in the same period. Keep unresolved claims open and avoid attributing intent from a trend line. Suppose a teammate forwards a screenshot offering a guaranteed quantity without explaining acquisition. You can record that the claim lacks a verifiable source and decline to use the screenshot as campaign evidence. That conclusion concerns the evidence provided. If a past team shared access, have the account owner check connections and security in the official app. Record any verified change with the relevant owner and avoid circulating credentials in the production file."
