          "The Bluesky official overview links to bsky.app and the mobile app downloads. Put the posting account, owner, official entry and recovery contact on the internal handoff sheet. Confirm the public profile link through the organization’s own website or another established route. Once signed in, check the visible bio, links and publishing time zone. Give reading and publishing separate entries in the activity log. For an agency-operated account, define the handoff and offboarding before the first shift. An editor’s ability to open the app does not authorize them to speak for the brand. Give editors and approvers a clear working route and keep credentials out of the handoff. A useful launch note also identifies which questions will be answered in public and which team owns the official help channel. Suppose the handle looks correct but the link in the profile leads to an expired campaign page. Fix the destination through the account owner before asking viewers to use it. Record when it changed so later replies point to the current page."
