          "The Bluesky starter pack guide describes a bundle of recommended accounts and custom feeds. When someone shares a pack, review its curator, intended audience, the recent activity of included accounts and any stated criteria. Membership does not establish a commercial relationship. A brand can start from the pack and check relevance account by account. For a home appliance desk, a broad founder pack may lead to useful people without surfacing questions about cleaning, repair or storage. Save a few relevant sources and revisit them with the same criteria. If the team maintains a pack, explain its editorial purpose, inclusion criteria and removal process. Leave an owner and a review date so a pack can evolve when accounts change hands or their focus shifts. Suppose the brand finds a specialist account through a pack and wants to contact its owner later. Record the original profile and published contact route rather than using the curator as proof of identity or authorization. The pack helped discovery. The profile and the account holder supply the evidence for any subsequent contact."
