          "An editorial log can use the original link, a short description of the question, the public reply, owner, deadline and status. Separate copy corrections, service cases and product facts needing confirmation. If five replies in one thread raise a similar question, group them as one internal item and describe the observed scope. They do not estimate the needs of everyone who saw the post. For a FAQ update, use the campaign measurement and logging guide to label the observation window and sample. Give the issue to the person who can resolve it in the approved system. Suppose the team sees a thread about replacement parts. The social editor can explain the published policy. The service owner checks individual eligibility privately. A product owner can clarify why documentation names two part numbers. Keep those actions on separate lines so a short public answer does not appear to resolve an individual case. After the issue closes, link to the corrected public guide if it will help other readers."
