          "按YouTube视频分享说明，可用分享按钮复制链接，并在支持的界面选择开始位置。项目记录同时保留原片、起止时间、相关画面和前后语境。假设 2:17 的字幕写“适用于户外”，但 2:22 紧接着给出“仅限遮雨环境”，引用时保留限定。字幕与音频不一致时，说明翻译或转写的来源。用另一台设备或未登录视图检查获准分享的人能打开。为演示、引述、品牌主张分别写出可查位置。",
          "The YouTube sharing guide describes copying a link and, where available, choosing a start point. Keep the original URL, start and end time, visible action and surrounding context in the project record. Suppose a caption at 2:17 says a product is suitable outdoors, and the presenter adds at 2:22 that it needs shelter from rain. Carry the condition into the note. If captions differ from the audio, identify the language and translation or transcription source. Test whether the intended reviewer can open the link on an appropriate device or signed-out view when the video is meant to be public. Give a demonstration, quote and brand claim their own pointers if they appear in different moments. One line can summarize what the clip supports and another can flag information missing from it. That helps the next reader reproduce the check quickly. If a timestamp link does not start at the intended frame on a device, the written time range still gives the reader an independent way to find the passage."
