          "Check the agreement and creator footage usage rights for screenshots, clips, sound, captions, edits and distribution. A link useful for research gives the reviewer a way to inspect evidence. It does not itself give an editor a license. Point the fact checker to the source and timecode, then list intended asset uses separately. If the client wants to put a clip in an ad, specify runtime, placements, markets, term and the parties whose permissions are needed. Mark outstanding clearance and keep a viable alternative, such as commissioning an independently approved demonstration. Saving a file locally cannot settle that permission. Suppose the creator approves a video excerpt but the original includes a third-party soundtrack. Record the visual approval and keep music clearance open, or propose a properly cleared replacement track. The new cut may need another review because the replacement affects pace and captions. Identify the approval owner for the actual version. Keep the evidence link available to reviewers even when the production plan changes to a new recording."
