          "Keep a follower snapshot when the question is about account scale. Use actual post reach when reviewing how a published asset traveled. Read relevant replies, saves or visits when the decision concerns a viewer question. Write the report question in one sentence before requesting exports. Suppose the brand is choosing between another product demo and a service explainer. The follower count sets context while the content and audience response can inform the production choice. Use the creator campaign measurement guide to agree on scope and relevant metrics. Give each observation a decision it can support instead of compressing different numbers into one account score. If the procurement form also asks for the follower count, include the date and keep that requirement separate. A reviewer may see that one post reached many accounts and still choose a narrower service video because the available feedback shows a concrete misunderstanding. Explain the decision and its source rather than assuming the largest count determines the next investment."
