          "The lululemon women’s size guide is an example of brand guidance that organizes sizing and measurements by product group. Before filming, record market, style identifier, tagged size, length or cut, and layering. Distinguish the manufacturer’s fit guidance from the wearer’s preference. The same letter across brands need not correspond to the same measurements. If the creator chooses to share measurements relevant to fit, collect only what the assignment needs. Separate accounts of fit are useful across bodies and preferences. No single wearer can answer every sizing question. Suppose two leggings have the same waist measurement at rest, but the rise and pocket placement differ. Record the construction detail and show what happened during the same move. Avoid treating a garment laid flat as equivalent to an on-body fitting. If a sample is unavailable in the preferred size, either delay the sizing claim or explain which sample was actually tested. Keep the official chart’s market and access date in the source record."
