          "The Bluesky official overview links its web app to bsky.app and provides mobile entry points. When a note says app.bluesky, preserve the words and identify whether they came from a browser field, an account signature or an internal note. Use the link from the official overview before entering account information. Check the host shown by the browser and the public page you actually opened. If an internal document reverses the address, correct the runbook and save the verified entry for later shifts. Suggestions, similar text and sponsored results are leads. Suppose a new editor receives a screenshot with the browser bar cut off. Ask for the trusted source of the link and open the official entry independently. You can confirm a destination without assuming the screenshot identified the genuine site. Keep the confirmed URL and date in the handoff so the next person does not repeat the ambiguity. An application bookmark should use the actual official destination, separate from the URL of a particular brand’s profile."
