          "Choose an uninterrupted reference take and then collect close-ups. Order the edit around the question, setup, action and result. Have a reviewer watch it at normal speed, then mark where a hand obscures the item or a caption passes too quickly. The Meta Reels editing announcement describes improvements to clip editing. Confirm the actual controls available to your account. Before speeding up a passage, check whether timing matters to the instruction. If a latch jams in one shot and opens in another, confirm the model and setup before joining them. Show a transition clearly if conditions changed. Suppose the second angle reveals a small safety catch. A cut that drops the first movement may make the instruction impossible to follow, so retain enough of both actions. Keep a review copy with timecodes so the producer can point to the exact moment that needs a new crop. Export the cleared file under a unique version and mark which one is approved. If a later edit changes the sequence, review the claim and captions again."
