          "The W3C captions guide treats captions as synchronized text for speech and meaningful non-speech sound. Watch muted and check whether the instruction, warnings and visual timing still make sense. Restore sound and review timing, volume and actual clearance for each track. Keep written instructions away from hands and product details. Inspect the phone preview for the publishing account, including overlays near the top, bottom and sides. If there are separate placement files, review each one in its planned crop. A voice cue may arrive before a hand moves in the wide edit and too late after a recut. Check the cue against the revision that will actually be uploaded. If auto-generated captions are used, correct names, measurements and terms from the demonstration. A second viewer who has not seen the script can help identify where the visual information is unclear. Record their observation and the timecode rather than revising every shot at once."
