          "报表上写完整字段、入口、帖子或广告 ID、账号、开始和结束日期、时区、取数时间和是否受投放影响。公开计数可以描述查看时看到的量级，广告面板可以针对活动的投放结果，奖励面板反映项目资格。即使三个界面都用 views 字样，也不意味着统计范围一致。用创作者活动数据指南先问管理团队要回答什么。若是广告预算，找具体活动；若是自然内容复盘，找对应帖子数据；若是创作者结算，走奖励面板。注意界面没有给出的定义，不用另一入口的说明代填。",
