          "TikTok ad video play definitions say the general six-second column can include reaching six seconds, fully playing a shorter video or receiving an eligible interaction within the first six seconds. A total in that column does not show that everyone watched six full seconds. Mark the condition when the asset itself is shorter. When comparing two runtimes, choose a metric that fits the task. If the product action appears at second eight, a six-second count cannot establish that viewers saw it. Check when the action occurs, which fields are available and what the next edit can test. A full view of a four-second teaser also exposes different information from a full view of a fifteen-second tutorial. Group them only when the report makes that scope clear. If you have an estimate of average play time, read its definition and preserve its denominator. Do not use it to infer that every viewer watched the same amount. In a campaign recap, write which version and time marker motivated the choice of a six-second or completion metric."
