          "The TikTok focused view objective guide describes video views optimization in Ads Manager. TikTok ad video play definitions list focused view columns with paid views and paid interactions for certain six- and fifteen-second products. Some columns depend on the ad product used. If a buyer wants a measure tied to time watched or a full shorter play, check that the selected column excludes events counted solely for early interaction. Report a paid interaction column with its actual definition and do not add it to unique viewers. Save the exact export label and product together. If the breakdown is unavailable, keep the aggregate and its limitations visible. Suppose two agencies both write focused views in a deck. Ask one to provide the export field and the other to identify its campaign objective. Similar shorthand can refer to different metrics. A procurement comparison can proceed once the units match. If they do not, the two results can remain useful as separate observations without being combined into a single ranking."
