          "Suppose one ad row has 10,000 impressions, 8,000 starts, 4,000 two-second views and 2,500 six-second views. Two-second views per impression is 40 percent, per start is 50 percent and six-second views per impression is 25 percent. Those are event ratios. They do not identify the share of distinct people who took an action. Use the engagement rate metric contract to label formulas, counts and windows. Preserve the early interaction condition when it applies to the six-second column. If two duration columns appear unexpectedly close, review the actual names, clip length and eligibility rules before suggesting a cause. Repeat the same method with the other sample. When costs enter the report, check currency, date window and whether the selected cost-per metric uses the same column. If an original export is absent, mark the calculation as illustrative or pending. A reader should be able to tell which observed result supports the next buying decision without guessing from a percentage in a slide."
