          "先写一句用户看完需要做什么，例如认识新产品、查看说明、提交表单或完成购买。再让投手核对实际账户与广告目标能否支持相应优化和报告。用创作者活动衡量指南约定主要事件、次要事件和观察窗。假设品牌要测试新安装页，先明确衡量落地页访问还是安装完成。一次点击或到达不代表安装完成。若只能获取访问数据，可先做更窄的流量试验。记录目标、预算、地区和停止条件。",
          "Start with what the viewer should do after the ad: recognize the product, read instructions, submit a form or buy. Have the media owner verify whether the objectives and optimization available in the account support that action. Use the creator campaign measurement guide to agree on the primary event, supporting events and observation window. Suppose the brand wants to test a new installation page. Decide whether the result is a page visit or a completed installation. A click or arrival cannot establish completion. If visits are the only reliable data, scope a narrower traffic test. Record the objective, budget, market and condition for stopping. A team may run a short test to validate a destination before testing a lower-funnel event. Mark the test purpose so later reviewers do not compare it directly with a sales campaign. Assign the owner who can confirm event delivery and the person who will act on the result. This keeps the launch from depending on a metric that the available setup cannot report."
