          "The Meta Instagram partnership ads announcement explains how advertisers can amplify eligible organic content or create a new ad using a creator or partner’s handle. Use the partnership ad permissions guide to record the brand and creator accounts, exact asset, permission route and expiration. Match the platform permission to the agreement. Organic publication approval establishes the scope of that post. The ability to select an ad still leaves asset and audio clearance to confirm. Keep credentials and usable access codes out of the project handoff. Have the relevant account owner handle identity changes. Suppose a brand has permission for one Reel from a creator and prepares a new cut with a different title and music. Review whether the agreement and current platform permission cover the actual new version. A clear record can show that the creator approved the edit, the correct ad account can run it and the publisher is authorized to use that identity. Give each item an owner and end date, then review renewal before the campaign runs beyond the term."
