          "Review the cleared asset, caption, ad identity, paid scope and audio together. FTC influencer disclosure guidance emphasizes making material connections clear where U.S. rules apply. Check the actual ad preview for applicable disclosure and platform labeling, as well as the original draft. If a 30-second creator review becomes an eight-second ad, check whether a usage limitation disappeared or an endorsement changed meaning. Review language, rights and applicable local requirements for a new market. Archive the approval for each version separately. Suppose a clip was licensed only for one month of paid use. A revised crop may still be within scope, but a longer campaign or new territory needs its own check. Record who can approve an extension and when to stop delivery if it is unavailable. Before launch, confirm that all reviewers inspected the same file and caption. If an editor updates a claim or soundtrack after approval, reopen the relevant review rather than relying on the old version’s clearance."
