          "Keep the campaign, ad set or ad identifier, attribution window, currency, delivery scope and extraction time. Impressions, reach, clicks, site sessions and orders use different counting rules. The Meta ads transparency explanation provides context for public ad information. Public visibility cannot substitute for an authorized delivery report. Where the asset also has an organic post, keep organic performance separate unless the reporting surface documents a combined measure. If clicks are high and sessions are lower, inspect page behavior, tags and metric definitions before deciding whether to revise the destination or the ad. Confirm who can see the needed aggregate. A change in attribution window can affect which actions appear in the report even with the same creative. Record the setup before comparing periods. If the campaign started in one market and then expanded, preserve both the earlier scope and the change date. The next buyer can check which observations are comparable instead of treating a single cumulative result as a complete explanation."
