          "The TikTok recommendation guide includes hashtags among content information and describes other inputs that can matter by surface. For each candidate, identify the footage, use case or question it matches. A brand can use a topic, a specific context and a series label where each has a purpose. In the kitchen example, organization is the topic, a small counter is the context and the series name helps people find more. If a broad tag implies a shopping ranking but the post shows storage, choose language that reflects the actual edit. Let the caption explain the subject naturally. Suppose two tags describe a similar action in different local phrasing. Keep both on the candidate list and check which wording appears in relevant examples. Choose one to test rather than stacking variants whose roles overlap. If a tag has a brand or protected campaign association, confirm the relationship before using it in promotional copy. Record the choice with the footage version so the next editor can reconstruct what was tested."
