          "Write which posts keep the current tag and which replace one use-case term. Use comparable topics, language, runtime, publishing windows and organic delivery where practical. Record differences the team cannot control. Use the creator campaign measurement guide to choose a fixed observation age, available metrics and unresolved questions. Pick a main outcome, such as relevant storage questions, and use views or visits as context. Use distinct pieces from a comparable series instead of repeatedly uploading the same clip to manufacture a comparison. If the opening and tag both changed, describe a comparison of two versions. Suppose one post received an outside share and the other did not. Retain the event and decide whether a new comparable test is needed. A publishing experiment can help a team learn which terms describe the work well. It does not randomly assign viewers or isolate every cause. Give the next editor the tag strings, actual captions, asset versions and source windows so a follow-up does not depend on a vague memory of the test."
