          "Brandwatch产品帮助中心把 Influence 定位为创作者发现与活动管理。试用时给出一个具体目标，例如找到能用目标语言做某产品演示的人。请工具产出可检查的候选、来源、数据日期及后续流程。在官方主页验证当前作品、地区、联系途径及需要人工确认的权限。不要只按粉丝数或工具评分判断。若名单中某个账号变名或作品失效，检查能否给状态、保留来源和移交给负责人。活动结果使用实际客户约定的字段。",
          "The Brandwatch product help center describes Influence as a creator discovery and campaign management product. Give the pilot a concrete task, such as finding someone who can demonstrate a particular product in the intended language. Ask for candidates with inspectable sources, data dates and a clear handoff. Confirm recent work, market, contact and permission through appropriate sources. A follower count or vendor score cannot establish fit by itself. If a profile changes its name or an example disappears, check whether staff can retain the observation, update the state and assign the follow-up. Use campaign metrics agreed with the client. Suppose two candidates have similar audience numbers but only one shows the required action. The original footage is stronger evidence about that production task. The data can help prioritize the review without replacing it. Give a second analyst the shortlist and check whether they can open the same sources and identify which evidence remains missing. A trial is more informative when it tests how a decision is explained as well as how quickly a list can be created."
